func _stamp_cutout(file_name: String, origin: Vector2i, footprint: Vector2i, blocked: bool = true, z: int = 7) -> void:
	var texture := _texture(FANTASY_CUTOUT_DIR + file_name)
	if texture == null:
		return
	var sprite := Sprite2D.new()
	sprite.name = "Cutout_%s" % file_name.get_basename()
	sprite.texture = texture
	sprite.centered = false
	sprite.texture_filter = CanvasItem.TEXTURE_FILTER_NEAREST
	sprite.z_index = z
